-- MySQL 8.4 LTS. Explicit InnoDB foreign keys and enforced CHECK constraints.
CREATE TABLE IF NOT EXISTS branches(id char(36) PRIMARY KEY DEFAULT (UUID()), name varchar(500) NOT NULL UNIQUE, next_sr integer NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS users(id char(36) PRIMARY KEY DEFAULT (UUID()), name varchar(500) NOT NULL, email varchar(500) NOT NULL, password_hash varchar(500) NOT NULL, role ENUM ('admin','branch_user') NOT NULL, branch_id char(36), active boolean NOT NULL DEFAULT true, must_change_password boolean NOT NULL DEFAULT true, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), CHECK ((role='admin' AND branch_id IS NULL) OR (role='branch_user' AND branch_id IS NOT NULL)), FOREIGN KEY (branch_id) REFERENCES branches(id), UNIQUE KEY users_email_ci(email)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS sessions(token_hash varchar(500) PRIMARY KEY, user_id char(36) NOT NULL, csrf_token varchar(500) NOT NULL, expires_at datetime(3) NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id), KEY sessions_expiry(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS sources(id char(36) PRIMARY KEY DEFAULT (UUID()), name varchar(500) NOT NULL, UNIQUE KEY sources_name_ci(name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS items(id char(36) PRIMARY KEY DEFAULT (UUID()), name varchar(500) NOT NULL, UNIQUE KEY items_name_ci(name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS depreciation_rates(id char(36) PRIMARY KEY DEFAULT (UUID()), category ENUM ('Computer Accessories','Furniture & Fitting','Land & Building','Machineries & Equipment','Medical Equipment') NOT NULL, rate numeric(5,2) NOT NULL CHECK(rate>0 AND rate<=100), UNIQUE(category,rate)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS assets(id char(36) PRIMARY KEY DEFAULT (UUID()), branch_id char(36) NOT NULL, sr_no integer NOT NULL, audit_book_ref varchar(500) NOT NULL, audit_year integer NOT NULL, date_purchased date NOT NULL, donation_source_id char(36) NOT NULL, item_id char(36) NOT NULL, category ENUM ('Computer Accessories','Furniture & Fitting','Land & Building','Machineries & Equipment','Medical Equipment') NOT NULL, dep_percent numeric(5,2) NOT NULL CHECK(dep_percent>0 AND dep_percent<=100), original_cost numeric(14,2) NOT NULL CHECK(original_cost>=1), status ENUM ('active','fully_depreciated') NOT NULL DEFAULT 'active', created_by char(36) NOT NULL, updated_by char(36), created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at datetime(3), deleted_at datetime(3), deleted_by char(36), version integer NOT NULL DEFAULT 1, UNIQUE(branch_id,sr_no), FOREIGN KEY (branch_id) REFERENCES branches(id), FOREIGN KEY (donation_source_id) REFERENCES sources(id), FOREIGN KEY (item_id) REFERENCES items(id), FOREIGN KEY (created_by) REFERENCES users(id), FOREIGN KEY (updated_by) REFERENCES users(id), FOREIGN KEY (deleted_by) REFERENCES users(id), KEY assets_branch_live(branch_id,deleted_at,date_purchased)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS depreciation_log(id char(36) PRIMARY KEY DEFAULT (UUID()), asset_id char(36) NOT NULL, period date NOT NULL, provision numeric(14,2) NOT NULL CHECK(provision>=0), wdv numeric(14,2) NOT NULL CHECK(wdv>=1), UNIQUE(asset_id,period), FOREIGN KEY (asset_id) REFERENCES assets(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS delete_requests(id char(36) PRIMARY KEY DEFAULT (UUID()), asset_id char(36) NOT NULL, requested_by char(36) NOT NULL, status ENUM ('pending','approved','rejected') NOT NULL DEFAULT 'pending', reviewed_by char(36), reason varchar(500) NOT NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), reviewed_at datetime(3), FOREIGN KEY (asset_id) REFERENCES assets(id), FOREIGN KEY (requested_by) REFERENCES users(id), FOREIGN KEY (reviewed_by) REFERENCES users(id), pending_asset_id char(36) GENERATED ALWAYS AS (CASE WHEN status='pending' THEN asset_id ELSE NULL END) STORED, UNIQUE KEY one_pending_request_per_asset(pending_asset_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS audit_trail(id char(36) PRIMARY KEY DEFAULT (UUID()), at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), actor_id char(36), action varchar(500) NOT NULL, entity varchar(500) NOT NULL, entity_id varchar(500) NOT NULL, branch_id char(36), detail text NOT NULL, before_data json, after_data json, FOREIGN KEY (actor_id) REFERENCES users(id), FOREIGN KEY (branch_id) REFERENCES branches(id), KEY audit_branch_time(branch_id,at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

